public class FastDateFormat_format_TriageGen4Test {

    @Test
    public void testFormat_WithTimeZoneForced_True() {
        // Scenario: mTimeZoneForced is true (via getInstance(pattern, timeZone))
        // The method should clone the calendar and set the specific timezone.
        String pattern = "yyyy-MM-dd HH:mm:ss";
        TimeZone forcedZone = TimeZone.getTimeZone("UTC");
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, forcedZone);

        Calendar calendar = Calendar.getInstance(TimeZone.getTimeZone("America/New_York"));
        calendar.set(2023, Calendar.OCTOBER, 27, 10, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        // Expected: The time should be converted to UTC
        // 10:00 AM NY (EDT is UTC-4) -> 14:00 UTC
        String expected = "2023-10-27 14:00:00";
        assertEquals(expected, result.toString());

        // Verify the original calendar was not modified (cloning check)
        assertEquals("America/New_York", calendar.getTimeZone().getID());
    }

    @Test
    public void testFormat_WithTimeZoneForced_False() {
        // Scenario: mTimeZoneForced is false (via getInstance(pattern))
        // The method should use the timezone provided by the calendar object itself.
        String pattern = "yyyy-MM-dd HH:mm:ss";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        TimeZone calendarZone = TimeZone.getTimeZone("GMT");
        Calendar calendar = Calendar.getInstance(calendarZone);
        calendar.set(2023, Calendar.JANUARY, 1, 12, 0, 0);
        calendar.set(Calendar.MILLISECOND, 0);

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        String expected = "2023-01-01 12:00:00";
        assertEquals(expected, result.toString());
    }

    @Test
    public void testFormat_WithExistingBuffer() {
        // Test that the method appends to the existing StringBuffer (via applyRules)
        String pattern = "yyyy";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern);

        Calendar calendar = Calendar.getInstance();
        calendar.set(2025, Calendar.DECEMBER, 25);

        StringBuffer buf = new StringBuffer("Year: ");
        StringBuffer result = fdf.format(calendar, buf);

        assertEquals("Year: 2025", result.toString());
    }

    @Test
    public void testFormat_WithDifferentLocale() {
        // Test that locale impacts formatting (e.g., month names if pattern used)
        String pattern = "MMMM";
        FastDateFormat fdf = FastDateFormat.getInstance(pattern, Locale.FRENCH);

        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.MAY, 1);

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        // May in French is "mai"
        assertEquals("mai", result.toString().toLowerCase());
    }

    @Test
    public void testFormat_WithDateStyles() {
        // Testing via the DateInstance factory methods to ensure coverage of different internal paths
        FastDateFormat fdf = FastDateFormat.getDateInstance(Calendar.LONG, Calendar.SHORT);
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.JUNE, 15);

        StringBuffer buf = new StringBuffer();
        StringBuffer result = fdf.format(calendar, buf);

        assertNotNull(result);
        assertFalse(result.length() == 0);
    }
}
